"use strict";
function enabledRounds(){return [1];}
function roundControlTools(number,r){return !can('rounds')||r.status==='ENDED'?'':'<button class="secondary" data-round-settings="1">Edit time</button>';}
function startReadiness(n){const c=S.data.start_checks?.[n];return !c?'':c.ready?`<p class="start-ready">Ready · ${c.eligible_count} teams</p>`:`<ul class="start-blockers">${c.blockers.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`;}
function eventControls(){const e=S.data.event,stopped=Object.values(e.rounds).every(r=>!['RUNNING','PAUSED'].includes(r.status));return `<section class="card"><div class="card-head"><h2>${esc(e.name)}</h2>${can('rounds')?'<button class="secondary" data-live-settings>Hunt settings</button>':''}</div><p>${roundSize(1)} riddles per team · 3 winners</p><p>Helpline: ${esc(e.settings.organizer_phone||'Not set')}</p>${S.access.role==='owner'?`<details><summary>Reset & backups</summary><button class="secondary" data-reset-hunt ${stopped?'':'disabled'}>Reset hunt</button>${e.last_backup?`<button class="secondary" data-download-backup="${esc(e.last_backup)}">Download backup</button>`:''}</details>`:''}</section>`;}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{
 if(b.hasAttribute('data-live-settings')){
  const e=S.data.event,draft=Object.values(e.rounds).every(r=>r.status==='DRAFT');
  modal('Hunt settings',`<label>Event name<input name="name" value="${esc(e.name)}" required maxlength="200"></label>${draft?`<label>Total riddles per team<input name="target_riddles" type="number" min="1" max="${e.riddles.length}" value="${roundSize(1)}" required></label><label>Start countdown (seconds)<input name="start_countdown_seconds" type="number" min="0" max="600" value="${e.settings.start_countdown_seconds??30}" required></label><label>Phone mode<select name="phone_mode"><option value="standard" ${!e.settings.require_kiosk?'selected':''}>Standard APK</option><option value="managed" ${e.settings.require_kiosk?'selected':''}>Managed kiosk</option></select></label><label>When hearts run out<select name="hearts"><option value="recover" ${e.settings.life_cooldown_ms?'selected':''}>Recover after 15 minutes</option><option value="eliminate" ${!e.settings.life_cooldown_ms?'selected':''}>Eliminate team</option></select></label>`:''}<label>Helpline number<input name="organizer_phone" type="tel" maxlength="26" value="${esc(e.settings.organizer_phone)}"></label><label>Team locations<select name="opponent_map">${[['live','Live GPS'],['coarse','Approximate'],['off','Off']].map(([v,t])=>`<option value="${v}" ${v===e.settings.opponent_map?'selected':''}>${t}</option>`).join('')}</select></label><label class="check"><input name="public_leaderboard" type="checkbox" ${e.public_leaderboard?'checked':''}>Projector leaderboard</label>`,async form=>{const f=new FormData(form),body={edit_revision:S.modalEditRevision,name:f.get('name'),organizer_phone:f.get('organizer_phone'),opponent_map:f.get('opponent_map'),public_leaderboard:form.elements.public_leaderboard.checked};if(draft){body.target_riddles=Number(f.get('target_riddles'));body.start_countdown_seconds=Number(f.get('start_countdown_seconds'));body.require_kiosk=f.get('phone_mode')==='managed';body.life_cooldown_ms=f.get('hearts')==='recover'?900000:0;}await api('/admin/live-settings',{method:'PUT',body:JSON.stringify(body)});await refresh(true);notify('Hunt settings saved.');});
 }
 if(b.dataset.roundSettings){const e=S.data.event,r=e.rounds[1],active=r.status!=='DRAFT',live=S.data.rounds?.[1]||r;
  modal('Hunt time',`<label>Time<select name="timing"><option value="unlimited" ${r.duration_ms===0?'selected':''}>No time limit</option><option value="timed" ${r.duration_ms>0?'selected':''}>Time limit</option></select></label><label>${active?'Minutes remaining':'Minutes'}<input name="minutes" type="number" min="1" max="240" value="${Math.ceil((live.remaining_ms??r.duration_ms)/60000)||60}" required></label>`,async form=>{const f=new FormData(form),body={edit_revision:S.modalEditRevision};if(f.get('timing')==='unlimited')body.duration_ms=0;else if(active)body.remaining_minutes=Number(f.get('minutes'));else body.duration_ms=Number(f.get('minutes'))*60000;await api('/admin/rounds/1/settings',{method:'PUT',body:JSON.stringify(body)});await refresh(true);notify('Time saved.');});
  const form=$('#modal-form'),update=()=>{const limited=form.elements.timing.value==='timed';form.elements.minutes.disabled=!limited;form.elements.minutes.closest('label').hidden=!limited;};form.elements.timing.onchange=update;update();
 }
 if(b.hasAttribute('data-reset-hunt'))modal('Reset hunt','<p>Saves a backup and clears progress.</p><label>Teams<select name="teams"><option value="keep">Keep accounts and phones</option><option value="clear">Remove all teams</option></select></label><label>Admin password<input name="password" type="password" required autocomplete="current-password"></label><label>Type RESET<input name="confirm" pattern="RESET" required></label>',async form=>{await api('/admin/reset',{method:'POST',body:JSON.stringify({edit_revision:S.modalEditRevision,password:form.elements.password.value,confirm:form.elements.confirm.value,keep_teams:form.elements.teams.value==='keep'})});form.elements.password.value='';await refresh(true);notify('Hunt reset.');},'Reset');
 if(b.dataset.downloadBackup)download(b.dataset.downloadBackup+'.json',await api('/admin/backups/'+b.dataset.downloadBackup));
}catch(e){notify(e.message,true);}});
